#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int *head = malloc((n + 1) * sizeof(int));
    int *to = malloc(2 * (n - 1) * sizeof(int));
    int *next = malloc(2 * (n - 1) * sizeof(int));
    int *parent = calloc(n + 1, sizeof(int));
    int *order = malloc(n * sizeof(int));
    int *stack = malloc(n * sizeof(int));
    int *subtree = malloc((n + 1) * sizeof(int));

    for (int i = 1; i <= n; i++) head[i] = -1;

    int edges = 0;
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);

        to[edges] = b;
        next[edges] = head[a];
        head[a] = edges++;

        to[edges] = a;
        next[edges] = head[b];
        head[b] = edges++;
    }

    int stack_size = 0, order_size = 0;
    stack[stack_size++] = 1;
    parent[1] = -1;

    while (stack_size > 0) {
        int u = stack[--stack_size];
        order[order_size++] = u;

        for (int e = head[u]; e != -1; e = next[e]) {
            int v = to[e];
            if (v != parent[u]) {
                parent[v] = u;
                stack[stack_size++] = v;
            }
        }
    }

    for (int i = 1; i <= n; i++) subtree[i] = 1;

    int answer = n;
    for (int i = order_size - 1; i > 0; i--) {
        int u = order[i];
        int size = subtree[u];
        int difference = abs(n - 2 * size);
        if (difference < answer) answer = difference;
        subtree[parent[u]] += size;
    }

    printf("%d\n", answer);

    free(head);
    free(to);
    free(next);
    free(parent);
    free(order);
    free(stack);
    free(subtree);
    return 0;
}
